using Microsoft.EntityFrameworkCore;
using PA.Tickets.Application.Foundations;
using PA.Tickets.Application.Reporting;
using PA.Tickets.Infrastructure.Execution;
using PA.Tickets.Infrastructure.Persistence;
namespace PA.Tickets.Infrastructure.Reporting;
public sealed class KpiService(TicketsDbContext db,ExecutionDbContext execution,IAuthorizationService authorization,TimeProvider clock):IKpiService
{
 static readonly TimeZoneInfo Zone=TimeZoneInfo.FindSystemTimeZoneById("Asia/Kolkata");
 static readonly IReadOnlyCollection<KpiDefinition> Defs=Build();
 static IReadOnlyCollection<KpiDefinition> Build(){var p=new[]{KpiPeriodKind.Day,KpiPeriodKind.Week,KpiPeriodKind.Month,KpiPeriodKind.Custom};var s=new[]{"client","department","team","service","category","subcategory","requestType","ticketType","priority","requester","assignee"};return new[]{D("SLA_COMPLIANCE","SLA Compliance","Percentage of qualifying SLA measurements completed within target.","Persisted SLA execution state; rows without BreachedAt meet SLA.","percentage",KpiDirection.HigherIsBetter,p,s),D("FIRST_RESPONSE_TIME","First Response Time","Average elapsed time to authoritative first response.","Ticket creation to FIRST_RESPONSE or RESPONSE_RECEIVED lifecycle event.","minutes",KpiDirection.LowerIsBetter,p,s),D("RESOLUTION_TIME","Resolution Time","Average elapsed time for tickets resolved in period.","Ticket creation to ResolvedAt.","minutes",KpiDirection.LowerIsBetter,p,s),D("OPEN_BACKLOG","Open Backlog","Open tickets at period end.","Configured open statuses at period end.","count",KpiDirection.LowerIsBetter,p,s,0),D("AVERAGE_TICKET_AGE","Average Ticket Age","Average age of open tickets.","Period end minus CreatedAt.","minutes",KpiDirection.LowerIsBetter,p,s),D("REOPEN_RATE","Reopen Rate","Percentage reopened in period.","Persisted REOPEN lifecycle events over authorized ticket population.","percentage",KpiDirection.LowerIsBetter,p,s),D("APPROVAL_TURNAROUND","Approval Turnaround","Average completed approval duration.","Approval CreatedAt to CompletedAt.","minutes",KpiDirection.LowerIsBetter,p,s),D("WAITING_TIME","Waiting Time","Average persisted waiting duration.","WaitingMinutes for waiting work items started in period.","minutes",KpiDirection.LowerIsBetter,p,s)};}
 static KpiDefinition D(string c,string n,string d,string def,string u,KpiDirection dir,IReadOnlyCollection<KpiPeriodKind> p,IReadOnlyCollection<string> s,decimal? t=null)=>new(c,n,d,def,u,dir,1,new DateTimeOffset(2026,1,1,0,0,0,TimeSpan.Zero),t,Precision:u=="count"?0:2,SupportedPeriods:p,ScopeDimensions:s);
 public IReadOnlyCollection<KpiDefinition> Catalogue()=>Defs;
 public KpiDefinition GetDefinition(string code)=>Defs.FirstOrDefault(x=>x.Code.Equals(code,StringComparison.OrdinalIgnoreCase))??throw new KeyNotFoundException("The requested KPI was not found.");
 public async Task<KpiResult> CalculateAsync(string code,KpiCalculationRequest request,long actor,string? correlationId,CancellationToken ct){var d=GetDefinition(code);var (start,end)=Period(request.Period);await authorization.EnsurePermissionAsync(actor,"TICKET_READ",null,ct);var t=await Authorized(actor,request.Scope??new(),ct);decimal? num=null,den=null,val=null;int pop=0;
 switch(d.Code){case "SLA_COMPLIANCE":var ids=t.Select(x=>x.Id);var q=execution.Slas.AsNoTracking().Where(x=>ids.Contains(x.TicketId)&&x.CompletedAt>=start&&x.CompletedAt<end);den=await q.CountAsync(ct);num=await q.CountAsync(x=>x.BreachedAt==null,ct);val=Ratio(num,den);pop=(int)den;break;
 case "FIRST_RESPONSE_TIME":var ev=from e in db.Events.AsNoTracking() join x in t on e.TicketId equals x.Id where e.At>=start&&e.At<end&&(e.Type=="FIRST_RESPONSE"||e.Type=="RESPONSE_RECEIVED") select new{x.CreatedAt,e.At};var er=await ev.ToListAsync(ct);pop=er.Count;den=pop;val=pop==0?null:Round(er.Average(x=>(x.At-x.CreatedAt).TotalMinutes));break;
 case "RESOLUTION_TIME":var rr=await t.Where(x=>x.ResolvedAt>=start&&x.ResolvedAt<end).Select(x=>new{x.CreatedAt,x.ResolvedAt}).ToListAsync(ct);pop=rr.Count;den=pop;val=pop==0?null:Round(rr.Average(x=>(x.ResolvedAt!.Value-x.CreatedAt).TotalMinutes));break;
 case "OPEN_BACKLOG":var os=await db.StatusDefinitions.AsNoTracking().Where(x=>x.Active&&x.IsOpen).Select(x=>x.Id).ToListAsync(ct);pop=await t.CountAsync(x=>os.Contains(x.StatusId),ct);den=pop;val=pop;break;
 case "AVERAGE_TICKET_AGE":var st=await db.StatusDefinitions.AsNoTracking().Where(x=>x.Active&&x.IsOpen).Select(x=>x.Id).ToListAsync(ct);var ages=await t.Where(x=>st.Contains(x.StatusId)&&x.CreatedAt<end).Select(x=>x.CreatedAt).ToListAsync(ct);pop=ages.Count;den=pop;val=pop==0?null:Round(ages.Average(x=>(end-x).TotalMinutes));break;
 case "REOPEN_RATE":var p=t.Where(x=>x.CreatedAt<end);den=await p.CountAsync(ct);var pi=p.Select(x=>x.Id);num=await db.Events.AsNoTracking().CountAsync(x=>pi.Contains(x.TicketId)&&x.At>=start&&x.At<end&&x.Type.Contains("REOPEN"),ct);pop=(int)den;val=Ratio(num,den);break;
 case "APPROVAL_TURNAROUND":var a=execution.ApprovalInstances.AsNoTracking().Where(x=>x.CompletedAt>=start&&x.CompletedAt<end&&t.Select(y=>y.Id).Contains(x.TicketId));var ar=await a.Select(x=>new{x.CreatedAt,x.CompletedAt}).ToListAsync(ct);pop=ar.Count;den=pop;val=pop==0?null:Round(ar.Average(x=>(x.CompletedAt!.Value-x.CreatedAt).TotalMinutes));break;
 case "WAITING_TIME":var w=t.SelectMany(x=>x.WorkItems).Where(x=>x.WaitingMinutes>0&&x.WaitingStartedAt>=start&&x.WaitingStartedAt<end);var wr=await w.Select(x=>x.WaitingMinutes).ToListAsync(ct);pop=wr.Count;den=pop;val=pop==0?null:Round(wr.Average());break;}
 return new(d.Code,d.Version,start,end,clock.GetUtcNow(),request.Scope??new(),num,den,val,d.Unit,d.Target,d.WarningThreshold,d.CriticalThreshold,Status(d,val),d.Precision,pop,correlationId);}
 async Task<IQueryable<TicketRow>> Authorized(long actor,KpiScope s,CancellationToken ct){var now=clock.GetUtcNow();var u=await db.AdministrationUsers.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==actor&&x.Active,ct)??throw new UnauthorizedAccessException();var admin=await(from m in db.AdministrationUserRoles.AsNoTracking() join r in db.AdministrationRoles.AsNoTracking() on m.RoleId equals r.Id where m.UserId==actor&&m.Active&&r.Active&&r.Code=="ADMINISTRATOR" select r.Id).AnyAsync(ct);var c=db.AdministrationUserClients.AsNoTracking().Where(x=>x.UserId==actor&&x.Active).Select(x=>x.ClientId);var q=admin?db.Tickets.AsNoTracking():db.Tickets.AsNoTracking().Where(x=>x.CurrentAssignee==actor||(u.DepartmentId.HasValue&&x.CurrentDepartmentId==u.DepartmentId)||(u.TeamId.HasValue&&x.CurrentTeamId==u.TeamId)||(x.ClientId.HasValue&&c.Contains(x.ClientId.Value)));if(s.ClientId.HasValue)q=q.Where(x=>x.ClientId==s.ClientId);if(s.DepartmentId.HasValue)q=q.Where(x=>x.CurrentDepartmentId==s.DepartmentId);if(s.TeamId.HasValue)q=q.Where(x=>x.CurrentTeamId==s.TeamId);if(s.ServiceId.HasValue)q=q.Where(x=>x.ServiceId==s.ServiceId);if(s.CategoryId.HasValue)q=q.Where(x=>x.CategoryId==s.CategoryId);if(s.RequestTypeId.HasValue)q=q.Where(x=>x.RequestTypeId==s.RequestTypeId);if(s.PriorityId.HasValue)q=q.Where(x=>x.PriorityId==s.PriorityId);if(s.RequesterId.HasValue)q=q.Where(x=>x.RequestedBy==s.RequesterId);if(s.AssigneeId.HasValue)q=q.Where(x=>x.CurrentAssignee==s.AssigneeId);if(s.TicketType.HasValue)q=q.Where(x=>x.TypeId==s.TicketType);return q;}
 static decimal? Ratio(decimal? n,decimal? d)=>d is null or 0?null:n/d*100m;static decimal Round(double x)=>decimal.Round((decimal)x,2,MidpointRounding.AwayFromZero);static decimal Round(int x)=>x;static KpiStatus Status(KpiDefinition d,decimal? v){if(v is null)return KpiStatus.NotApplicable;if(d.Target is null&&d.WarningThreshold is null&&d.CriticalThreshold is null&&d.TargetLower is null&&d.TargetUpper is null)return KpiStatus.Unconfigured;if(d.Direction==KpiDirection.TargetBand&&d.TargetLower.HasValue&&d.TargetUpper.HasValue)return v>=d.TargetLower&&v<=d.TargetUpper?KpiStatus.OnTarget:KpiStatus.Critical;if(!d.Target.HasValue)return KpiStatus.Unconfigured;var good=d.Direction==KpiDirection.HigherIsBetter?v>=d.Target:v<=d.Target;return good?KpiStatus.OnTarget:KpiStatus.Critical;}
 static (DateTimeOffset,DateTimeOffset) Period(KpiPeriodRequest r){if(r.Kind==KpiPeriodKind.Custom){if(r.From is null||r.To is null||r.From>=r.To)throw new ArgumentException("Invalid custom period.");return (At(r.From.Value),At(r.To.Value));}var d=r.Date??DateOnly.FromDateTime(DateTime.UtcNow);return(At(d),At(r.Kind switch{KpiPeriodKind.Day=>d.AddDays(1),KpiPeriodKind.Week=>d.AddDays(7),KpiPeriodKind.Month=>d.AddMonths(1),_=>d.AddDays(1)}));}static DateTimeOffset At(DateOnly d)=>new(TimeZoneInfo.ConvertTimeToUtc(d.ToDateTime(TimeOnly.MinValue),Zone));
}

